final case class Interval[A](lo: Option[A], hi: Option[A],
                             loClosed: Boolean = true, hiClosed: Boolean = true)
                            (implicit ord: Ordering[A]) {
  require((for (l <- lo; h <- hi) yield ord.lteq(l, h)).getOrElse(true), "lo > hi")

  def contains(v: A): Boolean =
    lo.forall(l => ord.lt(l, v) || (loClosed && ord.equiv(l, v))) &&
    hi.forall(h => ord.lt(v, h) || (hiClosed && ord.equiv(v, h)))
}

val billing = Interval(Some(d1), Some(d2), hiClosed = false)   // [d1, d2)
val fromThenOn = Interval(Some(d1), None)                      // [d1, +inf)

